201	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
202	        Collection<Owner> owners;
203	        if (lastName != null) {
204	            owners = this.clinicService.findOwnerByLastName(lastName);
205	        } else {
206	            owners = this.clinicService.findAllOwners();
207	        }
208	        if (owners.isEmpty()) {
209	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
210	        }
211	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
212	    }
