224	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
225	    @Override
226	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
227	        String telephone = toE164(ownerFieldsDto.getTelephone());
228	        if (telephone == null) {
229	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
230	        }
231	        String email = ownerFieldsDto.getEmail();
232	        if (email != null && !EMAIL_PATTERN.matcher(email).matches()) {
233	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
234	        }
235	        String address = normaliseAddress(ownerFieldsDto.getAddress());
236	        if (address.isEmpty()) {
237	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
238	        }
239	        boolean telephoneInUse = this.clinicService.findAllOwners().stream()
240	            .map(Owner::getTelephone)
241	            .map(OwnerRestControllerV1::toE164)
242	            .filter(existing -> existing != null)
243	            .anyMatch(telephone::equals);
244	        if (telephoneInUse) {
245	            return new ResponseEntity<>(HttpStatus.CONFLICT);
246	        }
247	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
248	        String lastNameKey = normaliseIdentity(ownerFieldsDto.getLastName());
249	        String addressKey = address;
250	        List<Owner> householdMembers = this.clinicService.findAllOwners().stream()
251	            .filter(existing ->
252	                normaliseIdentity(existing.getLastName()).equals(lastNameKey)
253	                    && normaliseAddress(existing.getAddress()).equals(addressKey))
254	            .toList();
255	        if (!householdMembers.isEmpty() && !sharesHousehold) {
256	            return new ResponseEntity<>(HttpStatus.CONFLICT);
257	        }
258	        String firstNameKey = normaliseIdentity(ownerFieldsDto.getFirstName());
259	        int namesakeCount = (int) this.clinicService.findAllOwners().stream()
260	            .filter(existing ->
261	                normaliseIdentity(existing.getFirstName()).equals(firstNameKey)
262	                    && normaliseIdentity(existing.getLastName()).equals(lastNameKey))
263	            .count();
264	        HttpHeaders headers = new HttpHeaders();
265	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
266	        owner.setNamesakeCount(namesakeCount);
267	        owner.setAddress(address);
268	        owner.setTelephone(telephone);
269	        owner.setEmail(email == null ? null : email.toLowerCase());
270	        if (owner.getRegistrationDate() == null) {
271	            owner.setRegistrationDate(LocalDate.now());
272	        }
273	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
274	        if (sharesHousehold && !householdMembers.isEmpty()) {
275	            String householdId = householdId(lastNameKey, addressKey);
276	            owner.setHouseholdId(householdId);
277	            for (Owner member : householdMembers) {
278	                if (member.getHouseholdId() == null) {
279	                    member.setHouseholdId(householdId);
280	                    this.clinicService.saveOwner(member);
281	                }
282	            }
283	        }
284	        this.clinicService.saveOwner(owner);
285	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
286	        headers.setLocation(UriComponentsBuilder.newInstance()
287	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
288	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
289	    }
