291	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
292	    @Override
293	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
294	        String telephone = toE164(ownerFieldsDto.getTelephone());
295	        if (telephone == null) {
296	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
297	        }
298	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
299	        if (currentOwner == null) {
300	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
301	        }
302	        String email = ownerFieldsDto.getEmail();
303	        if (email != null && !EMAIL_PATTERN.matcher(email).matches()) {
304	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
305	        }
306	        currentOwner.setAddress(ownerFieldsDto.getAddress());
307	        currentOwner.setCity(ownerFieldsDto.getCity());
308	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
309	        currentOwner.setLastName(ownerFieldsDto.getLastName());
310	        currentOwner.setTelephone(telephone);
311	        currentOwner.setEmail(email == null ? null : email.toLowerCase());
312	        this.clinicService.saveOwner(currentOwner);
313	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
314	    }
315	
316	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
317	    @Transactional
318	    @Override
319	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
320	        Owner owner = this.clinicService.findOwnerById(ownerId);
321	        if (owner == null) {
322	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
323	        }
324	        this.clinicService.deleteOwner(owner);
325	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
326	    }
