328	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
329	    @Override
330	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
331	        Owner owner = this.clinicService.findOwnerById(ownerId);
332	        if (owner == null) {
333	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
334	        }
335	        HttpHeaders headers = new HttpHeaders();
336	        Pet pet = petMapper.toPet(petFieldsDto);
337	        owner.setId(ownerId);
338	        pet.setOwner(owner);
339	        pet.getType().setName(null);
340	        this.clinicService.savePet(pet);
341	        PetDto petDto = petMapper.toPetDto(pet);
342	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
343	            .buildAndExpand(pet.getId()).toUri());
344	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
345	    }
346	
347	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
348	    @Override
349	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
350	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
351	        if (currentOwner != null) {
352	            Pet currentPet = this.clinicService.findPetById(petId);
353	            if (currentPet != null) {
354	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
355	                currentPet.setName(petFieldsDto.getName());
356	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
357	                this.clinicService.savePet(currentPet);
358	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
359	            }
360	        }
361	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
362	    }
363	
364	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
365	    @Override
366	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
367	        HttpHeaders headers = new HttpHeaders();
368	        Visit visit = visitMapper.toVisit(visitFieldsDto);
369	        Pet pet = new Pet();
370	        pet.setId(petId);
371	        visit.setPet(pet);
372	        this.clinicService.saveVisit(visit);
373	        VisitDto visitDto = visitMapper.toVisitDto(visit);
374	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
375	            .buildAndExpand(visit.getId()).toUri());
376	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
377	    }
378	
379	
380	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
381	    @Override
382	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
383	        Owner owner = this.clinicService.findOwnerById(ownerId);
384	        if (owner != null) {
385	            Pet pet = owner.getPet(petId);
386	            if (pet != null) {
387	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
388	            }
389	        }
390	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
391	    }
392	}
